files.content:
* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 650px;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
}

form {
  display: flex;
  flex-direction: column;
  gap: 20px;
  width: 500px;
  border: 1px solid #000;
  padding: 45px;
  background-color: #6dc1fd;
}

fieldset {
  display: grid;
  border: none;
  padding: 0;
}

label {
  display: block;
  font-weight: 800;
  font-size: 12px;
  text-transform: uppercase;
}

label:not(:last-child) {
  margin-bottom: 10px;
}

button {
  border: 1px solid #000;
  padding: 10px 65px;
  color: #000;
  font-family: inherit;
  font-weight: 800;
  font-size: inherit;
  text-transform: uppercase;
  background-color: #feafe8;
}

button:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

button:focus {
  outline: 2px solid #000;
  outline-offset: 0;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

label span {
  display: inline-block;
  width: 20px;
  height: 20px;
  margin-right: 5px;
  vertical-align: middle;
  background-color: #feafe8;
}

input[type='radio'] + span {
  border-radius: 50%;
}

/* Целый набор странных селекторов */

input[type='radio']:checked + span {
  border: 3px solid #fff;
  /* Тут пишем рамку */
}

